<template>
  <main class="min-h-screen bg-[#f5f6fa] px-4 py-6 text-[#20283b]">
    <div class="mx-auto max-w-[1177px]">
      <header class="flex items-end justify-between gap-4">
        <div><p class="m-0 text-[11px] font-bold tracking-[0.8px] text-[#5c52ee]">MY TASKS</p><h1 class="mt-3 text-[30px] font-medium">我的全部任务</h1><p class="mt-2 text-xs text-[#8994a8]">跨项目查看由当前用户创建的任务</p></div>
        <n-button :loading="loading" secondary @click="loadTasks">刷新</n-button>
      </header>
      <section class="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4">
        <div v-for="item in summary" :key="item.key" class="rounded-[11px] border border-[#e1e4eb] bg-white px-4 py-3"><span class="text-[11px] text-[#8994a8]">{{ item.label }}</span><strong class="mt-1.5 block text-xl font-semibold" :class="item.color">{{ item.value }}</strong></div>
      </section>
      <section class="mt-5 rounded-[14px] border border-[#dfe3eb] bg-white">
        <div class="flex flex-wrap items-center gap-2 border-b border-[#e8eaf0] px-4 py-4"><n-select v-model:value="filters.status" clearable size="small" class="!w-[145px]" placeholder="全部状态" :options="statusOptions" @update:value="resetAndLoad" /><n-select v-model:value="filters.taskType" clearable size="small" class="!w-[160px]" placeholder="全部类型" :options="typeOptions" @update:value="resetAndLoad" /><n-input-number v-model:value="filters.projectId" clearable size="small" class="!w-[150px]" placeholder="项目 ID" :min="1" @update:value="resetAndLoad" /><n-checkbox v-model:checked="filters.activeOnly" @update:checked="resetAndLoad">只看活动任务</n-checkbox></div>
        <div v-if="loading && !tasks.length" class="flex min-h-[300px] items-center justify-center text-sm text-[#8994a8]">正在加载任务...</div>
        <div v-else-if="errorMessage && !tasks.length" class="flex min-h-[300px] flex-col items-center justify-center gap-3"><p class="m-0 text-sm text-[#b45d64]">{{ errorMessage }}</p><n-button size="small" secondary @click="loadTasks">重试</n-button></div>
        <div v-else-if="!tasks.length" class="flex min-h-[300px] items-center justify-center text-sm text-[#8994a8]">暂无任务</div>
        <div v-else class="overflow-x-auto"><table class="w-full min-w-[900px] border-collapse text-left text-xs"><thead class="bg-[#fafafd] text-[11px] text-[#8994a8]"><tr><th class="px-5 py-3">任务</th><th class="px-3 py-3">项目 / 剧集</th><th class="px-3 py-3">状态</th><th class="px-3 py-3">进度</th><th class="px-3 py-3">模型</th><th class="px-3 py-3">创建时间</th><th class="px-5 py-3 text-right">操作</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id" class="border-t border-[#edf0f4] hover:bg-[#fcfcfe]"><td class="max-w-[250px] px-5 py-4"><strong class="block truncate font-medium">{{ task.title }}</strong><small class="mt-1 block text-[10px] text-[#9aa3b3]">#{{ task.id }} · {{ typeLabel(task.task_type) }}</small></td><td class="px-3 py-4 text-[#69758b]">项目 {{ task.project_id }}<span v-if="task.episode_id"> · 第 {{ task.episode_id }} 集</span></td><td class="px-3 py-4"><n-tag :bordered="false" size="small" :type="statusType(task.status)">{{ statusLabel(task.status) }}</n-tag></td><td class="w-[150px] px-3 py-4"><div class="flex items-center gap-2"><n-progress :percentage="task.progress" :show-indicator="false" :status="progressStatus(task.status)" class="min-w-[75px]" /><span class="w-9 text-right text-[10px]">{{ task.progress_indeterminate ? '处理中' : `${task.progress}%` }}</span></div><small v-if="task.stage" class="mt-1 block truncate text-[10px] text-[#a0a8b6]">{{ stageLabel(task.stage) }}</small></td><td class="max-w-[130px] truncate px-3 py-4 text-[#69758b]">{{ task.model_name || '--' }}</td><td class="whitespace-nowrap px-3 py-4 text-[#8994a8]">{{ formatDate(task.created_at) }}</td><td class="px-5 py-4 text-right"><n-button size="small" quaternary @click="openDetail(task)">详情</n-button><n-button v-if="task.task_type === 'SCRIPT_ANALYSIS' && task.status === 'FAILED'" size="small" quaternary type="warning" :loading="retryingTaskId === task.id" @click="retryTask(task)">重试</n-button><n-button v-if="task.can_cancel" size="small" quaternary type="error" @click="cancelTask(task)">取消</n-button></td></tr></tbody></table></div>
        <footer v-if="total > pageSize || tasks.length" class="flex items-center justify-between border-t border-[#e8eaf0] px-4 py-3"><span class="text-[11px] text-[#9aa3b3]">共 {{ total }} 项 · 第 {{ page + 1 }} / {{ pageCount }} 页</span><div class="flex gap-1.5"><n-button size="small" secondary :disabled="page <= 0 || loading" @click="changePage(page - 1)">‹</n-button><n-button size="small" secondary :disabled="page + 1 >= pageCount || loading" @click="changePage(page + 1)">›</n-button></div></footer>
      </section>
    </div>
    <n-drawer v-model:show="detailVisible" :width="drawerWidth" placement="right"><n-drawer-content v-if="selectedTask" :title="selectedTask.title" closable><div class="space-y-4"><n-tag :bordered="false" :type="statusType(selectedTask.status)">{{ statusLabel(selectedTask.status) }}
</n-tag><div class="rounded-[10px] bg-[#fafafd] p-3"><n-progress :percentage="selectedTask.progress" :show-indicator="false" :status="progressStatus(selectedTask.status)" /><p v-if="selectedTask.stage" class="mt-2 text-xs text-[#8994a8]">{{ stageLabel(selectedTask.stage) }}</p></div><div v-if="selectedTask.analysis_progress" class="rounded-[10px] border border-[#e2e6f5] bg-[#fbfcff] p-3"><div class="flex items-center justify-between gap-3"><span class="text-xs font-medium text-[#4c5870]">剧本解析进度</span><span class="text-[10px] text-[#8994a8]">{{ selectedTask.analysis_progress.stream ? '流式' : '非流式' }}</span></div><div class="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[11px] text-[#788399]"><span>已完成 {{ selectedTask.analysis_progress.completed }}/{{ selectedTask.analysis_progress.total }}</span><span>失败 {{ selectedTask.analysis_progress.failed }}</span><span>处理中 {{ selectedTask.analysis_progress.pending }}</span></div><div v-if="selectedTask.analysis_progress.current_type" class="mt-2 text-[11px] text-[#4f62c7]">当前：{{ analysisTypeLabel(selectedTask.analysis_progress.current_type) }}</div><div class="mt-3 space-y-2"><div v-for="item in selectedTask.analysis_progress.types" :key="item.type" class="rounded-[7px] border border-[#edf0f4] bg-white px-2.5 py-2"><div class="flex items-center justify-between gap-2"><span class="text-[11px] font-medium text-[#58647a]">{{ analysisTypeLabel(item.type) }}</span><n-tag size="tiny" :bordered="false" :type="analysisStatusType(item.status)">{{ analysisStatusLabel(item.status) }}</n-tag></div><div class="mt-1 flex items-center justify-between gap-2 text-[10px] text-[#9aa3b3]"><span>{{ item.model || '--' }} · {{ item.provider || '--' }}</span><span>{{ item.count }} 条结果</span></div><p v-if="item.error" class="mt-1 mb-0 text-[10px] leading-4 text-[#b45d64]">{{ item.error }}</p></div></div></div><dl class="grid grid-cols-2 gap-4 text-xs"><div><dt class="text-[#9aa3b3]">项目</dt><dd class="mt-1">{{ selectedTask.project_id }}</dd></div><div><dt class="text-[#9aa3b3]">剧集</dt><dd class="mt-1">{{ selectedTask.episode_id || '项目级' }}</dd></div><div><dt class="text-[#9aa3b3]">模型</dt><dd class="mt-1 truncate">{{ selectedTask.model_name || '--' }}</dd></div><div><dt class="text-[#9aa3b3]">尝试</dt><dd class="mt-1">{{ selectedTask.attempt }} / {{ selectedTask.max_attempts }}</dd></div></dl><div v-if="selectedTask.error_message" class="rounded-[10px] border border-[#f2dddd] bg-[#fffafa] p-3 text-xs text-[#8c5d63]">{{ selectedTask.error_message }}</div><n-button v-if="selectedTask.can_cancel" type="error" secondary block @click="cancelTask(selectedTask)">取消任务
</n-button><n-button v-if="selectedTask.task_type === 'SCRIPT_ANALYSIS' && selectedTask.status === 'FAILED'" type="warning" secondary block :loading="retryingTaskId === selectedTask.id" @click="retryTask(selectedTask)">发起重试</n-button></div></n-drawer-content></n-drawer>
  </main>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import type { TaskItem, TaskPage } from '~/types/tasks'
const http = useHttp(); const tasks = ref<TaskItem[]>([]); const selectedTask = ref<TaskItem | null>(null); const detailVisible = ref(false); const loading = ref(false); const errorMessage = ref(''); const retryingTaskId = ref<number | null>(null); const drawerWidth = ref(470); const page = ref(0); const pageSize = ref(20); const total = ref(0); const counts = ref<Record<string, number>>({}); const filters = reactive<{ projectId: number | null; status: string | null; taskType: string | null; activeOnly: boolean }>({ projectId: null, status: null, taskType: null, activeOnly: false }); let pollTimer: ReturnType<typeof setInterval> | null = null; let requestSequence = 0
const message = useMessage(); const statusOptions = [{ label: '等待中', value: 'PENDING' }, { label: '排队中', value: 'QUEUED' }, { label: '制作中', value: 'RUNNING' }, { label: '取消中', value: 'CANCEL_REQUESTED' }, { label: '已完成', value: 'SUCCEEDED' }, { label: '失败', value: 'FAILED' }, { label: '已取消', value: 'CANCELLED' }]; const typeOptions = [{ label: '剧本解析', value: 'SCRIPT_ANALYSIS' }, { label: '资产提取', value: 'ASSET_EXTRACTION' }, { label: '画面生成', value: 'IMAGE_GENERATION' }, { label: '图片编辑', value: 'IMAGE_EDIT' }, { label: '角色配音', value: 'VOICEOVER' }, { label: '音乐生成', value: 'MUSIC' }, { label: '音效生成', value: 'SOUND_EFFECT' }, { label: '字幕生成', value: 'SUBTITLE' }, { label: '视频合成', value: 'COMPOSITION' }]
const pageCount = computed(() => Math.max(1, Math.ceil(total.value / pageSize.value))); const activeCount = computed(() => ['PENDING', 'QUEUED', 'RUNNING', 'CANCEL_REQUESTED'].reduce((sum, status) => sum + (counts.value[status] || 0), 0)); const summary = computed(() => [{ key: 'active', label: '活动任务', value: activeCount.value, color: 'text-[#6654ee]' }, { key: 'queued', label: '排队中', value: (counts.value.PENDING || 0) + (counts.value.QUEUED || 0), color: 'text-[#d0872b]' }, { key: 'success', label: '已完成', value: counts.value.SUCCEEDED || 0, color: 'text-[#2f9a73]' }, { key: 'failed', label: '失败', value: counts.value.FAILED || 0, color: 'text-[#c56b73]' }])
async function loadTasks() { const sequence = ++requestSequence; loading.value = true; errorMessage.value = ''; try { const params: Record<string, unknown> = { page: page.value, page_size: pageSize.value }; if (filters.projectId) params.project_id = filters.projectId; if (filters.status) params.status = filters.status; if (filters.taskType) params.task_type = filters.taskType; if (filters.activeOnly) params.status = ['PENDING', 'QUEUED', 'RUNNING', 'CANCEL_REQUESTED']; const response = await http.get<TaskPage>('/tasks', params); if (sequence !== requestSequence) return; tasks.value = response.list || []; total.value = response.total || 0; page.value = response.page || 0; pageSize.value = response.page_size || 20; counts.value = response.counts || {}; if (selectedTask.value && detailVisible.value) { try { selectedTask.value = await http.get<TaskItem>(`/projects/${selectedTask.value.project_id}/tasks/${selectedTask.value.id}`) } catch { /* 保留上一次详情 */ } } } catch (error) { if (sequence === requestSequence) errorMessage.value = error instanceof Error ? error.message : '任务加载失败' } finally { if (sequence === requestSequence) loading.value = false } }
async function openDetail(task: TaskItem) { selectedTask.value = task; detailVisible.value = true; try { selectedTask.value = await http.get<TaskItem>(`/projects/${task.project_id}/tasks/${task.id}`) } catch (error) { message.warning(error instanceof Error ? error.message : '任务详情加载失败') } }
async function cancelTask(task: TaskItem) { if (!task.can_cancel || !window.confirm(`确定取消“${task.title}”吗？`)) return; try { const response = await http.post<{ status: string; can_cancel: boolean }>(`/projects/${task.project_id}/tasks/${task.id}/cancel`); task.status = response.status; task.can_cancel = response.can_cancel; await loadTasks() } catch (error) { message.error(error instanceof Error ? error.message : '任务取消失败') } }
async function retryTask(task: TaskItem) { if (task.task_type !== 'SCRIPT_ANALYSIS' || task.status !== 'FAILED' || retryingTaskId.value !== null) return; retryingTaskId.value = task.id; try { const response = await http.post<{ task_id: string; status: string }>(`/projects/${task.project_id}/script/analysis-tasks/${task.id}/retry`); const nextTaskId = Number(response.task_id); if (Number.isInteger(nextTaskId) && nextTaskId > 0 && detailVisible.value) { selectedTask.value = await http.get<TaskItem>(`/projects/${task.project_id}/tasks/${nextTaskId}`) }; message.success('已发起重试'); await loadTasks() } catch (error) { message.error(error instanceof Error ? error.message : '发起重试失败') } finally { retryingTaskId.value = null } }
function resetAndLoad() { page.value = 0; void loadTasks() }; function changePage(next: number) { page.value = next; void loadTasks() }; function statusLabel(value: string) { return Object.fromEntries(statusOptions.map((item) => [item.value, item.label]))[value] || value }; function typeLabel(value: string) { return Object.fromEntries(typeOptions.map((item) => [item.value, item.label]))[value] || value }; function stageLabel(value: string) { return ({ RUNNING: '正在执行', ANALYZE_CHARACTER: '正在解析角色', ANALYZE_SCENE_BACKGROUND: '正在解析场景', ANALYZE_PROP: '正在解析道具', RESULT_STAGED: '解析结果已暂存', PARTIAL_RESULT_STAGED: '部分解析结果已暂存', FAILED: '执行失败', QUEUED: '排队中' } as Record<string, string>)[value] || value.replaceAll('_', ' ').toLowerCase() }; function analysisTypeLabel(value: string) { return ({ CHARACTER: '角色', SCENE_BACKGROUND: '场景', PROP: '道具' } as Record<string, string>)[value] || value }; function analysisStatusLabel(value: string) { return ({ PENDING: '待处理', RUNNING: '解析中', SUCCEEDED: '已完成', FAILED: '失败' } as Record<string, string>)[value] || value }; function analysisStatusType(value: string): 'default' | 'success' | 'warning' | 'error' | 'info' { return ({ SUCCEEDED: 'success', FAILED: 'error', RUNNING: 'info', PENDING: 'default' } as Record<string, 'default' | 'success' | 'warning' | 'error' | 'info'>)[value] || 'default' }; function statusType(value: string): 'default' | 'success' | 'warning' | 'error' | 'info' { return ({ SUCCEEDED: 'success', FAILED: 'error', CANCELLED: 'default', CANCEL_REQUESTED: 'warning', RUNNING: 'info', QUEUED: 'warning', PENDING: 'default' } as Record<string, 'default' | 'success' | 'warning' | 'error' | 'info'>)[value] || 'default' }; function progressStatus(value: string): 'default' | 'success' | 'warning' | 'error' { return value === 'FAILED' ? 'error' : value === 'SUCCEEDED' ? 'success' : value === 'CANCELLED' ? 'warning' : 'default' }; function formatDate(value: string | null) { return value ? new Date(value).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '--' }
onMounted(async () => { drawerWidth.value = Math.min(470, Math.max(320, window.innerWidth - 24)); await loadTasks(); pollTimer = setInterval(() => { if (document.visibilityState === 'visible' && activeCount.value > 0) void loadTasks() }, 4000) }); onBeforeUnmount(() => { if (pollTimer) clearInterval(pollTimer) })
</script>
